ControlPropertyState.AutoRuleBindingString:
// ---- Step A: scalars ----
UpdateContext({sA:
  With(
    {
      tick: ctxTick + 1,
      playing: ctxMode = "Playing"
    },
    {
      tick: tick,
      playing: playing,
      // consume one queued hop (set by the direction buttons) per tick
      frogCol: If(playing, Min(12, Max(0, ctxFrogCol + Switch(ctxHop, "L", -nfHopCols, "R", nfHopCols, 0))), ctxFrogCol),
      frogRow: If(playing, Min(12, Max(0, ctxFrogRow + Switch(ctxHop, "U", -1, "D", 1, 0))), ctxFrogRow)
    }
  )
});
// ---- Step B: move the lane objects (pool) ----
UpdateContext({
  sLanes: ForAll(ctxLanes As o,
    If(!o.Active || !sA.playing, o, Patch(o, {X: Mod(o.X + o.Dir * o.Speed + 16, 16)})))
});
// ---- Step C: collisions and mode transitions ----
UpdateContext({sC:
  With(
    {
      modeTicks0: Max(0, ctxModeTicks - 1)
    },
    {
      modeTicks0: modeTicks0,
      nextMode:
        If(ctxMode = "Ready" && modeTicks0 = 0, "Playing",
        If(ctxMode = "GameOver" && modeTicks0 = 0, "Attract",
        ctxMode))
    }
  )
});
// ---- Step D: commit ----
UpdateContext({
  ctxTick: sA.tick,
  ctxFrame: If(Mod(sA.tick, 5) = 0, 1 - ctxFrame, ctxFrame),
  ctxMode: sC.nextMode,
  ctxModeTicks: If(sC.nextMode = ctxMode, sC.modeTicks0, Switch(sC.nextMode, "Ready", 40, "GameOver", 200, 0)),
  ctxFrogCol: sA.frogCol,
  ctxFrogRow: sA.frogRow,
  ctxHop: "",
  ctxLanes: sLanes
})

Rules.InvariantScript:
With({k: Lower(Right(Self.Text, 1))},
  UpdateContext({ctxHopQueued: Switch(k, "w", "U", "i", "U", "s", "D", "k", "D", "a", "L", "j", "L", "d", "R", "l", "R", ctxHopQueued)}));
Reset(Self)
